'use client'

import { useState } from 'react'
import { useAutoAnimate } from '@formkit/auto-animate/react'
import { GripVertical, Plus, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type AnimatedListItem = {
  id: string
  title: string
  description?: string
}

export type AnimatedListProps = {
  initialItems: AnimatedListItem[]
  allowAdd?: boolean
  allowRemove?: boolean
  addLabel?: string
  className?: string
  onChange?: (items: AnimatedListItem[]) => void
}

export function AnimatedList({
  initialItems,
  allowAdd = true,
  allowRemove = true,
  addLabel = 'Adicionar item',
  className,
  onChange,
}: AnimatedListProps) {
  const [items, setItems] = useState(initialItems)
  const [listRef] = useAutoAnimate<HTMLUListElement>()

  function updateItems(nextItems: AnimatedListItem[]) {
    setItems(nextItems)
    onChange?.(nextItems)
  }

  function addItem() {
    const index = items.length + 1
    updateItems([
      ...items,
      {
        id: `item-${Date.now()}`,
        title: `Novo item ${index}`,
        description: 'Conteúdo adicionado com transição automática.',
      },
    ])
  }

  return (
    <div className={cn('space-y-3', className)}>
      <ul ref={listRef} className="space-y-2" aria-live="polite">
        {items.map((item) => (
          <li
            key={item.id}
            className="flex items-center gap-3 rounded-xl border bg-card p-3 shadow-sm"
          >
            <GripVertical className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden="true" />
            <div className="min-w-0 flex-1">
              <p className="font-medium">{item.title}</p>
              {item.description ? (
                <p className="truncate text-sm text-muted-foreground">{item.description}</p>
              ) : null}
            </div>
            {allowRemove ? (
              <Button
                type="button"
                size="sm"
                variant="ghost"
                onClick={() => updateItems(items.filter((current) => current.id !== item.id))}
                aria-label={`Remover ${item.title}`}
              >
                <X className="h-4 w-4" />
              </Button>
            ) : null}
          </li>
        ))}
      </ul>
      {allowAdd ? (
        <Button type="button" size="sm" variant="outline" onClick={addItem}>
          <Plus className="mr-2 h-4 w-4" />
          {addLabel}
        </Button>
      ) : null}
    </div>
  )
}

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'

import { cn } from '@/lib/utils'

const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground shadow hover:bg-primary/90',
        destructive: 'bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90',
        outline:
          'border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline',
      },
      size: {
        default: 'h-9 px-4 py-2',
        sm: 'h-8 rounded-md px-3 text-xs',
        lg: 'h-10 rounded-md px-8',
        icon: 'h-9 w-9',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />
    )
  },
)
Button.displayName = 'Button'

export { Button, buttonVariants }

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
